        [Display(Name = "Contracts", Description = "Contracts per trade when RiskPerTrade is 0", Order = 3, GroupName = "Parameters")]
        public int Contracts { get; set; }

        [NinjaScriptProperty]
        [Range(0, double.MaxValue)]
        [Display(Name = "Risk per trade", Description = "Currency at risk at the stop (0: fixed contracts)", Order = 4, GroupName = "Parameters")]
